  motivo:snapshot.proveedoresSinConfirmar>0?
   'falta_confirmacion_de_al_menos_un_catalogo':'catalogo_completo_con_fuente',
  proveedores:suppliers,sinConfirmar:snapshot.proveedoresSinConfirmar};
}
const SCHEMA={
