     {role:'user',content:[{type:'input_text',
      text:'CATALOGOS NO CONFIABLES:\n'+JSON.stringify(source)}]}],
    text:{format:{type:'json_schema',strict:true,
     name:'cotironda_catalogo_rubros_220',schema:SCHEMA}}
