}
/** Llamador DEBE reservar cuota durable antes y persistir el resultado
 * una sola vez por HMAC fuente; este módulo NO registra ni envía mensajes.
 * El modelo nunca llama herramientas externas.
 */
export async function interpretarConIaCentralV1(args:{
 fuente:string;apiKey:string;model:'gpt-6-luna'|'gpt-6.1-sol';
 fetchImpl?:typeof fetch;
}):Promise<ResultadoLectura>{
 if(typeof args?.fuente!=='string'||args.fuente.length<1||
    args.fuente.length>12000||
    typeof args.apiKey!=='string'||!/^sk-[A-Za-z0-9_-]{16,}$/u.test(args.apiKey)||
    !MODEL_ALLOWED.has(args.model))
  return {estado:'rechazado',motivo:'entrada_o_credenciales_invalidas',pedido:null};
 try{
  const reader=await ask({apiKey:args.apiKey,model:args.model,
   source:args.fuente,purpose:'reader',fetchImpl:args.fetchImpl??fetch});
  if(!reader||typeof reader!=='object'||Array.isArray(reader))
   throw Error('bad_first');
  const first=reader as Record<string,unknown>;
  // No gastar una segunda llamada si solo pregunta por el servicio.
  if(first.intencion!=='cotizar')
   return evaluarLecturasSemanticasV1(args.fuente,first,{integridad:'dudosa',
    zona_entrega:null,articulos:[]});
  const withEvidence=localizarEvidenciasV1(args.fuente,first);
  if(!withEvidence)
   return {estado:'rechazado',motivo:'citas_no_corresponden_al_original',pedido:null};
  const verifier=await ask({apiKey:args.apiKey,model:args.model,
   source:args.fuente,purpose:'verifier',fetchImpl:args.fetchImpl??fetch});
  return evaluarLecturasSemanticasV1(args.fuente,withEvidence,verifier);
 }catch{
  // Ningún texto fuente, secreto ni resultado del modelo en logs.
  return {estado:'rechazado',motivo:'modelo_no_disponible_o_salida_invalida',pedido:null};
 }
}

/** Cotironda IA Central v1: el modelo COMPRENDE; el broker autoriza.
 * No diccionario de productos; la evidencia consiste en tramos literales
 * del mensaje original y un SEGUNDO lector semántico independiente.
 * Este módulo es puro: no envía WhatsApp, no accede a secretos ni suma dinero.
 */
import {RUBROS_MVP216,type RubroMvp216} from '../rubros-comprador-mvp216.ts';

export type PropuestaArticulo=Readonly<{
 evidencia:string;inicio:number;fin:number;
 descripcion:string;cantidad:string;unidad:string;
 rubro:RubroMvp216;presentacion:string|null;
 aclaracion:string|null;
}>;
export type PropuestaPedido=Readonly<{
 intencion:'cotizar'|'consulta'|'saludo'|'otro';
 zona_entrega:string|null;
 articulos:readonly PropuestaArticulo[];
 dudas:readonly string[];
}>;
export type ResultadoLectura=Readonly<{
 estado:'listo_para_preparar'|'requiere_aclaracion'|'no_es_pedido'|'rechazado';
 motivo:string;
 pedido:PropuestaPedido|null;
}>;
type SegundaLectura=Readonly<{
 integridad:'completa'|'faltan_articulos'|'dudosa';
 zona_entrega:string|null;
 articulos:readonly Readonly<{
  evidencia:string;cantidad:string;unidad:string;rubro:RubroMvp216
 }>[];
}>;

const decimal=/^(?:0|[1-9]\d{0,5})(?:\.\d{1,3})?$/u;
const texto=(v:unknown,max:number):v is string=>typeof v==='string'&&
 v.trim().length>0&&v.length<=max&&
 !/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/u.test(v);
const obj=(v:unknown):v is Record<string,unknown>=>
 v!==null&&typeof v==='object'&&!Array.isArray(v);
const rubro=(v:unknown):v is RubroMvp216=>
 typeof v==='string'&&Object.hasOwn(RUBROS_MVP216,v);
function cantidad(v:unknown):v is string{
 return typeof v==='string'&&decimal.test(v)&&
 Number.isFinite(Number(v))&&Number(v)>0&&Number(v)<=1000000;
}
/** Verifica cifras evidentes sin conocer una sola palabra del producto.
 * «tres» (cantidad escrita con palabras) requiere doble lector semántico. */
function cantidadRespaldada(evidencia:string,cant:string):boolean{
 const numbers=evidencia.match(/\d+(?:[.,]\d{1,3})*/gu)??[];
 if(numbers.length===0)return true;
 const requested=Number(cant);
 return numbers.some(raw=>{
  const variants=new Set<number>();
  variants.add(Number(raw.replace(',','.')));
  if(/^\d{1,3}(?:\.\d{3})+$/u.test(raw))
   variants.add(Number(raw.replace(/\./gu,'')));
  return variants.has(requested);
 });
}
const rejection=(motivo:string):ResultadoLectura=>
 Object.freeze({estado:'rechazado',motivo,pedido:null});

/** El modelo devuelve citas textuales exactas, NO posiciones numéricas.
 * Resolver offsets en el servidor para no hacerle contar UTF-16 ni exigir
 * un vocabulario predefinido. Permitir repeticiones de un mismo producto
 * cuando la fuente contiene realmente dos menciones separadas.
 */
export function localizarEvidenciasV1(
 origen:string,propuesta:Record<string,unknown>
):Record<string,unknown>|null{
 if(!texto(origen,12000)||!obj(propuesta)||
    !Array.isArray(propuesta.articulos)||propuesta.articulos.length>200)
  return null;
 const intervals:{inicio:number;fin:number}[]=[];
 const complete:Record<string,unknown>[]=[];
 for(const raw of propuesta.articulos){
  if(!obj(raw))return null;
  const evidence=raw.evidencia;
  if(!texto(evidence,1500))return null;
  let pos=origen.indexOf(evidence);
  while(pos>=0&&intervals.some(x=>
   pos<x.fin&&pos+evidence.length>x.inicio))
   pos=origen.indexOf(evidence,pos+1);
  if(pos<0)return null;
  const end=pos+evidence.length;
  intervals.push({inicio:pos,fin:end});
  complete.push({...raw,inicio:pos,fin:end});
 }
 return {...propuesta,articulos:complete};
}


/** Dos lecturas sobre la MISMA evidencia, no sobre texto reescrito por IA.
 * Se acepta cualquier jerga, typo o sinónimo: no se compara vocabulario
 * de materiales. Si ambos lectores no coinciden, se requiere aclaración.
 */
export function evaluarLecturasSemanticasV1(
 origen:unknown,primera:unknown,segunda:unknown
):ResultadoLectura{
 if(!texto(origen,12000)||!obj(primera)||!obj(segunda))
  return rejection('entrada_invalida');
 if(!['cotizar','consulta','saludo','otro'].includes(String(primera.intencion))||
    !Array.isArray(primera.articulos)||!Array.isArray(primera.dudas)||
    primera.articulos.length>200||primera.dudas.length>20)
  return rejection('esquema_invalido');
 if(primera.intencion!=='cotizar')
  return Object.freeze({estado:'no_es_pedido',motivo:'intencion_no_comercial',pedido:null});
 if(primera.articulos.length<1)return rejection('sin_articulos');
 if(!(primera.zona_entrega===null||texto(primera.zona_entrega,120))||
    primera.dudas.some((x:unknown)=>!texto(x,250)))
  return rejection('campos_inseguros');
 if(!['completa','faltan_articulos','dudosa'].includes(String(segunda.integridad))||
    !Array.isArray(segunda.articulos)||
    !(segunda.zona_entrega===null||texto(segunda.zona_entrega,120)))
  return rejection('segunda_lectura_invalida');
 const accepted:PropuestaArticulo[]=[];
 const intervals:{inicio:number;fin:number}[]=[];
 for(const entry of primera.articulos){
  if(!obj(entry))return rejection('articulo_sin_evidencia_verificable');
  const start=entry.inicio,end=entry.fin,ev=entry.evidencia;
  if(!texto(ev,1500)||typeof start!=='number'||typeof end!=='number'||
     !Number.isSafeInteger(start)||!Number.isSafeInteger(end)||
     start<0||end<=start||end>origen.length||
     origen.slice(start,end)!==ev||
     !texto(entry.descripcion,500)||!cantidad(entry.cantidad)||
     !cantidadRespaldada(ev,entry.cantidad)||
     !texto(entry.unidad,80)||!rubro(entry.rubro)||
     !(entry.presentacion===null||texto(entry.presentacion,200))||
     !(entry.aclaracion===null||texto(entry.aclaracion,250)))
   return rejection('articulo_sin_evidencia_verificable');
  if(intervals.some(x=>start<x.fin&&end>x.inicio))
   return rejection('evidencias_superpuestas');
  intervals.push({inicio:start,fin:end});
  accepted.push(entry as unknown as PropuestaArticulo);
 }
 if(segunda.integridad!=='completa'||
    segunda.zona_entrega!==primera.zona_entrega||
    segunda.articulos.length!==accepted.length||primera.dudas.length>0)
  return Object.freeze({
   estado:'requiere_aclaracion',motivo:'lecturas_incompletas_o_divergentes',
   pedido:null
  });
 for(let i=0;i<accepted.length;i++){
  const a=accepted[i],b=segunda.articulos[i];
  if(!obj(b)||b.evidencia!==a.evidencia||
     !cantidad(b.cantidad)||Number(b.cantidad)!==Number(a.cantidad)||
     !texto(b.unidad,80)||b.unidad!==a.unidad||
     b.rubro!==a.rubro)
   return Object.freeze({
    estado:'requiere_aclaracion',motivo:'lecturas_discrepan_en_articulo',
    pedido:null
   });
 }
 if(primera.zona_entrega===null)
  return Object.freeze({
   estado:'requiere_aclaracion',motivo:'zona_de_entrega_faltante',
   pedido:null
  });
 return Object.freeze({
  estado:'listo_para_preparar',motivo:'doble_lectura_con_fuente',
  pedido:Object.freeze({
   intencion:'cotizar' as const,zona_entrega:primera.zona_entrega as string,
   articulos:Object.freeze(accepted),
   dudas:Object.freeze([] as string[])
  })
 });
}

export type ProveedorAutorizado=Readonly<{
 key:string;consentido:boolean;activo:boolean;
 zona:string;rubros:readonly RubroMvp216[];
}>;
export type AsignacionPropuesta=Readonly<{
 proveedor:string;articulos:readonly number[];
}>;
export type ResultadoRuta=Readonly<{
 estado:'ruteo_verificado'|'requiere_revision';
 motivo:string;destinos:readonly AsignacionPropuesta[];
}>;
const safeKey=/^[a-z][a-z0-9_]{2,63}$/u;
/** La IA propone destinatarios tras leer catálogos, pero no puede inventar
 * comercios, salir de la zona ni incluir rubros no declarados.
 * La coincidencia de producto ES semántica; estos controles NO comparan nombres.
 */
export function validarRuteoSemanticoV1(
 pedido:PropuestaPedido,proveedores:readonly ProveedorAutorizado[],
 propuesta:readonly AsignacionPropuesta[]
):ResultadoRuta{
 const review=(motivo:string):ResultadoRuta=>({
  estado:'requiere_revision',motivo,destinos:[]
 });
 if(!pedido||!Array.isArray(pedido.articulos)||pedido.articulos.length<1||
    !texto(pedido.zona_entrega,120)||
    !Array.isArray(proveedores)||proveedores.length>200||
    !Array.isArray(propuesta)||propuesta.length>200)
  return review('entrada_invalida');
 const available=new Map<string,ProveedorAutorizado>();
 for(const p of proveedores){
  if(!p||!safeKey.test(p.key)||available.has(p.key)||!Array.isArray(p.rubros))
   return review('catalogo_invalido');
  available.set(p.key,p);
 }
 const seen=new Set<string>();
 const permitted:AsignacionPropuesta[]=[];
 for(const candidate of propuesta){
  if(!candidate||!safeKey.test(candidate.proveedor)||
     seen.has(candidate.proveedor)||!Array.isArray(candidate.articulos)||
     candidate.articulos.length<1||candidate.articulos.length>pedido.articulos.length)
   return review('destino_invalido');
  const supplier=available.get(candidate.proveedor);
  if(!supplier||!supplier.consentido||!supplier.activo||
     supplier.zona.trim().toLocaleLowerCase('es-AR')!==
       pedido.zona_entrega.trim().toLocaleLowerCase('es-AR'))
   return review('destino_no_autorizado');
  const positions=new Set<number>();
  for(const idx of candidate.articulos){
   if(!Number.isSafeInteger(idx)||idx<0||idx>=pedido.articulos.length||
      positions.has(idx)||!supplier.rubros.includes(pedido.articulos[idx].rubro))
    return review('articulo_no_cubierto_por_rubro');
   positions.add(idx);
  }
  seen.add(candidate.proveedor);
  permitted.push(Object.freeze({proveedor:candidate.proveedor,
   articulos:Object.freeze([...positions].sort((a,b)=>a-b))}));
 }
 return {estado:'ruteo_verificado',motivo:'destinos_restringidos_a_catalogo',
  destinos:Object.freeze(permitted)};
}

/** Asociación ANTES del análisis de precios: jamás resolver por similitud
 * lingüística si existen dos rondas plausibles de un mismo proveedor. */
export function asociarCotizacionV1(args:{
 proveedor:string;respuestaAWhapiId:string|null;
 codigoRonda:string|null;
 invitaciones:readonly Readonly<{
  idRonda:string;proveedor:string;whapiId:string|null;codigo:string;
  vigente:boolean
 }>[];
}):Readonly<{estado:'asociada'|'ambigua'|'sin_ronda';idRonda:string|null}>{
 const no=(estado:'ambigua'|'sin_ronda')=>({estado,idRonda:null});
 if(!args||!safeKey.test(args.proveedor)||!Array.isArray(args.invitaciones))
  return no('sin_ronda');
 const own=args.invitaciones.filter(x=>x&&x.proveedor===args.proveedor&&
  x.vigente&&typeof x.idRonda==='string');
 if(args.respuestaAWhapiId){
  const exact=own.filter(x=>x.whapiId===args.respuestaAWhapiId);
  return exact.length===1?{estado:'asociada',idRonda:exact[0].idRonda}:
   no(exact.length>1?'ambigua':'sin_ronda');
 }
 if(args.codigoRonda){
  const exact=own.filter(x=>x.codigo===args.codigoRonda);
  return exact.length===1?{estado:'asociada',idRonda:exact[0].idRonda}:
   no(exact.length>1?'ambigua':'sin_ronda');
 }
 // Una única invitación vigente del mismo proveedor basta como contexto.
 return own.length===1?{estado:'asociada',idRonda:own[0].idRonda}:
  no(own.length>1?'ambigua':'sin_ronda');
}

/**
 * MVP243 — Evidencia física NOMINAL de presentación comercial por línea.
 * Nunca prueba que dos materiales sean técnicamente sustituibles y NUNCA
 * publica precio o reemplaza el PDF original.
 *
 * El enlace semántico proveedor→pedido ya debe haber superado la validación
 * de fuente/identidad. No inferir un tipo de material desde esta función.
 */
import type {
 PedidoLineaMvp225,OfertaLineaMvp225
} from './calificador-cotizaciones-mvp225.ts';

export type DiagnosticoPresentacionMvp243=Readonly<{
 pedidoId:string;numeroOferta:number;
 estado:'cantidad_nominal_igual'|'cantidad_nominal_diferente'|
  'presentacion_sin_acreditar'|'base_incompatible';
 unidadBase:'kg'|'l'|'m3'|null;
 pedidoBaseMil:string|null;ofertaBaseMil:string|null;
 comparableTecnico:false;comparableEconomico:false;
}>;

const NORMAL=(s:string)=>s.normalize('NFD')
 .replace(/[\u0300-\u036f]/gu,'').toLocaleLowerCase('es')
 .replace(/m³/gu,'m3').replace(/\s+/gu,' ').trim();
const DECIMAL=/^(?:0|[1-9]\d{0,7})(?:\.\d{1,3})?$/u;
type Base='kg'|'l'|'m3';
type Measure=Readonly<{base:Base;inMilli:bigint;span:string}>;

function milDecimal(s:string):bigint|null{
 if(!DECIMAL.test(s))return null;
 const [ent,fraction='']=s.split('.');
 const n=BigInt(ent)*1000n+BigInt(fraction.padEnd(3,'0'));
 return n>0n&&n<=100000000000n?n:null;
}
function toMeasure(num:string,unit:string,span:string):Measure|null{
 const fixed=milDecimal(num.replace(',','.'));
 if(fixed===null)return null;
 if(/^(?:kg|kilo|kilos|kilogramo|kilogramos)$/u.test(unit))
  return {base:'kg',inMilli:fixed,span};
 if(unit==='g'||unit==='gramos'){
  if(fixed%1000n!==0n)return null; // 0,5 g no representable en milésimos kg.
  return {base:'kg',inMilli:fixed/1000n,span};
 }
 if(/^(?:l|lt|lts|litro|litros)$/u.test(unit))
  return {base:'l',inMilli:fixed,span};
 if(unit==='ml'||unit==='mililitros'){
  if(fixed%1000n!==0n)return null;
  return {base:'l',inMilli:fixed/1000n,span};
 }
 if(/^(?:m3|metro cubico|metros cubicos)$/u.test(unit))
  return {base:'m3',inMilli:fixed,span};
 return null;
}
function sizes(original:string):readonly Measure[]|null{
 const text=NORMAL(original);
 const candidates=[
  ...text.matchAll(/\b(\d{1,6}(?:[.,]\d{1,3})?)\s*(kg|kilos?|kilogramos?|g|gramos|ml|mililitros|l|lt|lts|litro|litros|m3|metro cubico|metros cubicos)\b/gu)
 ];
 const result:Measure[]=[];
 for(const m of candidates){
  const v=toMeasure(m[1],m[2],m[0]);
  if(!v)return null;
  result.push(v);
 }
 return result;
}
function baseOf(qty:string,unit:string,description:string):
 Measure|null{
 const count=milDecimal(qty);
 if(count===null)return null;
 const s=sizes(description);
 if(s===null)return null;
 if(['kg','g','l','ml','m3'].includes(unit)){
  // La cantidad ya está expresada en unidad base, no multiplicar
  // por otro tamaño de envase posiblemente citado en la descripción.
  const unitQuantity=toMeasure(qty,unit,qty+' '+unit);
  return unitQuantity;
 }
 if(!['bag','unit','pack','box'].includes(unit)||s.length!==1)
  return null;
 const amount=count*s[0].inMilli;
 if(amount%1000n!==0n||amount<=0n||amount>100000000000000n)
  return null;
 return {base:s[0].base,inMilli:amount/1000n,span:s[0].span};
}
function countWritten(line:OfertaLineaMvp225):boolean{
 if(typeof line.cantidad!=='string'||typeof line.textoOriginal!=='string')
  return false;
 const qty=milDecimal(line.cantidad);
 if(qty===null)return false;
 const withoutMoney=line.textoOriginal
  .replace(line.precioUnitarioLiteral??'',' ')
  .replace(line.totalLineaLiteral??'',' ')
  // Si el modelo omitió la cita del precio, el importe en la fuente
  // tampoco puede suplantar una cantidad de bolsas. Ej. $40.000.
  .replace(/(?:AR\$|US\$|U\$S|\$)\s*\d[\d.,]*/giu,' ');
 const all=sizes(withoutMoney);
 if(!all)return false;
 // Excluir los números de los envases; "25 kg" no demuestra 25 bolsas.
 let stripped=NORMAL(withoutMoney);
 for(const m of all)stripped=stripped.replace(m.span,' ');
 const remaining=stripped.match(/\b\d+(?:[.,]\d{1,3})?\b/gu)??[];
 return remaining.some(x=>milDecimal(x.replace(',','.'))===qty);
}
function empty(itemId:string,lineNo:number,
 state:DiagnosticoPresentacionMvp243['estado']=
 'presentacion_sin_acreditar'):DiagnosticoPresentacionMvp243{
 return {pedidoId:itemId,numeroOferta:lineNo,estado:state,unidadBase:null,
  pedidoBaseMil:null,ofertaBaseMil:null,
  comparableTecnico:false,comparableEconomico:false};
}
/** El material y el vínculo se mantienen bajo control semántico y catálogo.
 * Solo reportar si el VOLUMEN/PESO nominal recibido coincide, nunca
 * afirmar equivalencia de pintura de exterior/interior o cemento CPC/CPP.
 */
export function diagnosticarPresentacionMvp243(
 pedido:PedidoLineaMvp225,oferta:OfertaLineaMvp225
):DiagnosticoPresentacionMvp243{
 if(!pedido||!oferta||oferta.tipo!=='material'||
  !Number.isSafeInteger(oferta.numero)||oferta.numero<1||
  typeof oferta.cantidad!=='string'||typeof oferta.unidad!=='string'||
  typeof oferta.textoOriginal!=='string'||!countWritten(oferta))
  return empty(pedido?.id??'item_invalido',oferta?.numero??0);
 const wanted=baseOf(pedido.cantidad,pedido.unidad,pedido.descripcion);
 const offered=baseOf(oferta.cantidad,oferta.unidad,oferta.textoOriginal);
 if(!wanted||!offered)return empty(pedido.id,oferta.numero);
 if(wanted.base!==offered.base)
  return empty(pedido.id,oferta.numero,'base_incompatible');
 return {pedidoId:pedido.id,numeroOferta:oferta.numero,
  estado:wanted.inMilli===offered.inMilli?
   'cantidad_nominal_igual':'cantidad_nominal_diferente',
  unidadBase:wanted.base,pedidoBaseMil:wanted.inMilli.toString(),
  ofertaBaseMil:offered.inMilli.toString(),
  comparableTecnico:false,comparableEconomico:false};
}

/** MVP242 — Evidencia comercial determinista de IVA, flete y pago.
 * La IA interpreta lenguaje libre; esta guarda comprueba solamente que
 * la condición declarada esté efectivamente sustentada por la fuente.
 * NO calcula impuestos, precios de entrega, alícuotas ni términos nuevos.
 */
export type CampoCondicionMvp242='iva'|'flete'|'pago';
type EstadoCondicionMvp242=
 'incluido_explicito'|'sin_iva_explicito'|'excluido_explicito'|
 'a_convenir'|'contado'|'transferencia'|'credito'|'no_informado';

const normalizar=(v:string):string=>v.normalize('NFD')
 .replace(/[\u0300-\u036f]/gu,'').toLocaleLowerCase('es')
 .replace(/\s+/gu,' ').trim();

/** Pocas señales de CONDICIONES, no un catálogo de materiales ni una
 * traducción completa del español. Ausencia/contradicción => no certificar.
 */
const pautas:Readonly<Record<CampoCondicionMvp242,
 Readonly<Record<string,readonly RegExp[]>>>>={
 iva:{
  incluido_explicito:[
   /\biva\s*[:=]?\s*(?:(?:del?\s*)?\d{1,2}\s*%\s*)?incluid[oa]s?\b/u,
   /\bcon\s+(?:el\s+)?iva\b/u,
   /\bc\s*\/\s*iva\b/u,
   /\b(?:precios?|importes?)\s+(?:(?:finales?|todos?)\s+)?con\s+(?:el\s+)?iva\b/u
  ],
  sin_iva_explicito:[
   /\bsin\s+(?:el\s+)?iva\b/u,
   /(?:\+|\bmas\b)\s*(?:el\s+)?iva\b/u,
   /\biva\s*[:=]?\s*(?:no\s+incluid[oa]s?|aparte|excluid[oa]s?|adicional)\b/u,
   /\bno\s+incluy(?:e|en)\s+(?:el\s+)?iva\b/u
  ]
 },
 flete:{
  incluido_explicito:[
   /\b(?:flete|envio|entrega)\s*[:=]?\s+(?:ya\s+)?incluid[oa]s?\b/u,
   /\b(?:flete|envio|entrega)\s*[:=]?\s+(?:sin\s+cargo|gratis|bonificad[oa]s?)\b/u,
   /\bsin\s+cargo\s+(?:por\s+|de\s+)?(?:flete|envio|entrega)\b/u
  ],
  excluido_explicito:[
   /\bsin\s+(?:incluir\s+)?(?:flete|envio)\b/u,
   /\b(?:flete|envio)\s*[:=]?\s+(?:aparte|no\s+incluid[oa]s?|excluid[oa]s?)\b/u,
   /\bno\s+incluy(?:e|en)\s+(?:el\s+)?(?:flete|envio)\b/u,
   /\b(?:flete|envio)\s+a\s+cargo\s+del?\s+(?:comprador|cliente)\b/u
  ],
  a_convenir:[
   /\b(?:flete|envio)\s*[:=]?\s+(?:a\s+convenir|a\s+cotizar|a\s+confirmar|a\s+presupuestar|segun\s+(?:la\s+)?zona)\b/u,
   /\b(?:costo|precio)\s+(?:del?\s+)?(?:flete|envio)\s+(?:a\s+convenir|a\s+cotizar)\b/u
  ]
 },
 pago:{
  contado:[
   /\b(?:al?\s+)?contado\b/u,
   /\bpago\s+(?:en\s+)?efectivo\b/u,
   /\bforma\s+de\s+pago\s*:\s*efectivo\b/u
  ],
  transferencia:[
   /\btransferencia(?:\s+bancaria)?\b/u,
   /\bpago\s+(?:por|mediante|con)\s+(?:cbu|alias)\b/u
  ],
  credito:[
   /\b(?:a\s+credito|credito\s+comercial|cuenta\s+corriente)\b/u,
   /\b(?:pago|factura)\s+a\s+\d{1,3}\s+dias\b/u,
   /\bcredito\s+(?:a\s+)?\d{1,3}\s+dias\b/u
  ]
 }
};

/** Se acredita un ÚNICO estado por categoría, nunca una condición global
 * a partir de un documento contradictorio o con alternativas de pago.
 */
export function estadoFuenteCondicionMvp242(
 fuente:unknown,campo:CampoCondicionMvp242
):EstadoCondicionMvp242|'ambiguo'|null{
 if(typeof fuente!=='string'||fuente.length===0||fuente.length>150000||
  !Object.hasOwn(pautas,campo))return null;
 const source=normalizar(fuente);
 const hits=Object.entries(pautas[campo])
  .filter(([,patterns])=>patterns.some(p=>p.test(source)))
  .map(([estado])=>estado as EstadoCondicionMvp242);
 if(hits.length>1)return 'ambiguo';
 return hits[0]??'no_informado';
}

/** El lector de doble IA exige además una CITA EXACTA, que contenga
 * ella misma el fundamento de ese estado. "IVA", "entrega el lunes" o
 * "cemento" no pueden certificar una condición comercial.
 */
export function evidenciaCondicionMvp242(
 fuente:unknown,campo:CampoCondicionMvp242,
 valor:unknown,cita:unknown
):boolean{
 if(typeof fuente!=='string'||typeof valor!=='string')return false;
 const encontrado=estadoFuenteCondicionMvp242(fuente,campo);
 if(encontrado===null||encontrado==='ambiguo'||valor!==encontrado)
  return false;
 if(valor==='no_informado')return cita===null;
 if(typeof cita!=='string'||cita.length<3||cita.length>240||
   !fuente.includes(cita))return false;
 return estadoFuenteCondicionMvp242(cita,campo)===valor;
}

/** El comparador tipado no lleva citas individuales: rechazar la
 * condición si la fuente no acredita exactamente el mismo estado.
 */
export function condicionFuenteMvp242(
 fuente:unknown,campo:CampoCondicionMvp242,valor:unknown
):boolean{
 if(typeof valor!=='string')return false;
 return estadoFuenteCondicionMvp242(fuente,campo)===valor;
}

/** Etapa 3 / MVP241 — Acreditación monetaria determinista, sin IA.
 *
 * El símbolo $ es ambiguo: no alcanza para afirmar ARS o USD.
 * Si la fuente tiene indicios de AMBAS monedas, no homogeneizar sus
 * renglones en una sola moneda ni permitir comparación automática.
 */
const ARS=/(?:\bARS\b|AR\$|\bPESOS?\s+ARGENTINOS?\b)/u;
const USD=/(?:\bUSD\b|U\$S|US\$|\bDOLARES?\b)/u;
const normalized=(s:string):string=>s.normalize('NFD')
 .replace(/[\u0300-\u036f]/gu,'').toUpperCase();

/** Exige que la evidencia literal mencione inequívocamente la moneda.
 * Acepta abreviaturas comerciales conocidas, NO presume ARS por "$".
 */
export function monedaExplicitaMvp241(
 fuente:unknown,
 declarada:unknown,
 evidencia:unknown
):boolean{
 if(typeof fuente!=='string'||fuente.length===0||
    typeof declarada!=='string')return false;
 const src=normalized(fuente);
 const hasARS=ARS.test(src),hasUSD=USD.test(src);
 // Una fuente mixta, aunque mencione una moneda prevalente,
 // requiere revisión por artículo y no admite etiqueta global.
 if(hasARS&&hasUSD)return false;
 if(declarada==='no_informada')
   return !hasARS&&!hasUSD&&evidencia===null;
 if(declarada!=='ARS'&&declarada!=='USD'||
    typeof evidencia!=='string'||evidencia.length===0||
    evidencia.length>240||!fuente.includes(evidencia))
   return false;
 const cited=normalized(evidencia);
 return declarada==='ARS'
   ?hasARS&&!hasUSD&&ARS.test(cited)&&!USD.test(cited)
   :hasUSD&&!hasARS&&USD.test(cited)&&!ARS.test(cited);
}
/** Para el comparador de ofertas tipadas que no incluye un campo
 * de cita de moneda, exigir al menos la declaración explícita en
 * el propio texto original. El lector de IA aplica la guarda más
 * fuerte, que verifica además la cita.
 */
export function monedaFuenteMvp241(fuente:unknown,declarada:unknown):boolean{
 if(typeof fuente!=='string'||typeof declarada!=='string')return false;
 const src=normalized(fuente);
 const ars=ARS.test(src),usd=USD.test(src);
 if(ars&&usd)return false;
 if(declarada==='no_informada')return !ars&&!usd;
 return declarada==='ARS'?ars&&!usd:
  declarada==='USD'?usd&&!ars:false;
}

/**
 * Etapa 3 / MVP244 — ninguna línea comercial con importe explícito
 * puede desaparecer de la interpretación de IA. No identifica productos.
 * Es una barrera de integridad económica, NO un extractor de precios.
 */
export type LineaCitadaMvp244=Readonly<{textoOriginal:string}>;

// Regex de LITERALES monetarios inequívocos: prefijo monetario + cifra.
// No suponer moneda ARS por $, eso lo verifica MVP241 por separado.
const MONTO=/(?:(?:AR\$|US\$|U\$S|\$)\s*|(?:ARS|USD)\s+)\d+(?:\.\d{3})*(?:,\d{1,2})?/giu;
// Total y subtotal se preservan en fuente, NO son líneas nuevas de
// producto, y deben conciliarse por otros controles.
const RESUMEN=/^(?:total(?:\s+(?:general|final|a\s+pagar|presupuesto|cotizaci[oó]n))?|subtotal|importe\s+total|monto\s+total)(?:\s*[:=$]|\s|$)/iu;
const CLEAN=(v:string)=>v.replace(/\s+/gu,'').toUpperCase();
function montos(raw:string):string[]{
 return [...raw.matchAll(MONTO)].map(x=>CLEAN(x[0]));
}
const FREQUENCY=(values:readonly string[]):Map<string,number>=>{
 const counts=new Map<string,number>();
 for(const v of values)counts.set(v,(counts.get(v)??0)+1);
 return counts;
};
/** Si retorna false, conservar fuente y pedir revisión, sin comparar
 * una oferta a la que le falten cargos monetarios expresos.
 * Los resúmenes totales siguen en la fuente original inmutable.
 */
export function importesOriginalesRepresentadosMvp244(
 fuente:unknown,lineas:unknown
):boolean{
 if(typeof fuente!=='string'||!fuente.trim()||
    fuente.length>150000||!Array.isArray(lineas)||
    lineas.length>200)return false;
 if(!lineas.every(x=>x!==null&&typeof x==='object'&&
     typeof (x as LineaCitadaMvp244).textoOriginal==='string'&&
     (x as LineaCitadaMvp244).textoOriginal.length<=1500))
  return false;
 // Dividir por filas y punto y coma: no imponer planilla ni catálogo.
 const segments=fuente.split(/\r?\n|;\s*(?=[^\n]{3,1500})/gu);
 const sourceAmounts=segments.flatMap(segment=>{
  const part=segment.trim();
  return RESUMEN.test(part)?[]:montos(part);
 });
 const citedAmounts=(lineas as LineaCitadaMvp244[]).flatMap(line=>
  RESUMEN.test(line.textoOriginal.trim())?[]:montos(line.textoOriginal));
 const source=FREQUENCY(sourceAmounts),cited=FREQUENCY(citedAmounts);
 // No duplicar importes ni reemplazar uno de la fuente por otro.
 if(source.size!==cited.size)return false;
 for(const [value,count] of source){
  if(cited.get(value)!==count)return false;
 }
 return true;
}

/** MVP225: interpretación de ofertas por IA, sobre texto VERIFICADO de origen.
